ALTER TABLE public.saved_patients ADD COLUMN IF NOT EXISTS patient_workspace_id uuid REFERENCES public.workspaces(id);
ALTER TABLE public.provider_contacts ADD COLUMN IF NOT EXISTS workspace_mfn_id text;
CREATE OR REPLACE FUNCTION public.saved_patient_account_link_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND NEW.patient_workspace_id IS NOT DISTINCT FROM OLD.patient_workspace_id THEN RETURN NEW; END IF;
IF NEW.patient_workspace_id IS NULL THEN RETURN NEW; END IF;
IF NOT public.can_manage_account_connections(NEW.workspace_id) OR NOT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=NEW.workspace_id AND w.account_type IN ('facility','hospital')) OR NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.workspace_a=least(NEW.workspace_id,NEW.patient_workspace_id) AND c.workspace_b=greatest(NEW.workspace_id,NEW.patient_workspace_id)) OR NOT EXISTS(SELECT 1 FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id JOIN public.user_profiles p ON p.user_id=m.user_id JOIN auth.users a ON a.id=m.user_id WHERE w.id=NEW.patient_workspace_id AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND a.email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Patient not available'; END IF;
INSERT INTO public.account_security_audit(user_id,sender_mfn_id,workspace_id,workspace_mfn_id,event_type,result) VALUES(auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),NEW.workspace_id,(SELECT mfn_id FROM public.workspaces WHERE id=NEW.workspace_id),'saved_patient_account_attachment',NEW.id::text);
RETURN NEW; END $$;
CREATE TRIGGER z_saved_patient_account_link_guard BEFORE INSERT OR UPDATE ON public.saved_patients FOR EACH ROW EXECUTE FUNCTION public.saved_patient_account_link_guard();
CREATE OR REPLACE FUNCTION public.list_facility_authorized_patients(_source uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('savedPatientId',s.id,'patientWorkspaceId',s.patient_workspace_id,'patientFirstName',s.first_name,'patientLastName',s.last_name,'patientPhone',s.phone,'patientEmail',s.email,'transportType',CASE WHEN s.mobility='stretcher' THEN 'gurney' WHEN s.mobility='wheelchair' THEN 'wheelchair' ELSE 'ambulatory' END,'facilityMfnId',w.mfn_id)),'[]'::jsonb) FROM public.saved_patients s JOIN public.workspaces w ON w.id=s.workspace_id JOIN public.account_business_connections c ON c.active AND c.workspace_a=least(w.id,_source) AND c.workspace_b=greatest(w.id,_source) WHERE public.can_manage_account_connections(_source) AND w.account_type IN ('facility','hospital') AND w.status='active' AND NOT w.is_test_account AND s.kind='patient' AND s.active AND s.patient_workspace_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.account_business_connections p WHERE p.active AND p.workspace_a=least(w.id,s.patient_workspace_id) AND p.workspace_b=greatest(w.id,s.patient_workspace_id)) AND EXISTS(SELECT 1 FROM public.account_business_connections p WHERE p.active AND p.workspace_a=least(_source,s.patient_workspace_id) AND p.workspace_b=greatest(_source,s.patient_workspace_id)) $$;
REVOKE ALL ON FUNCTION public.list_facility_authorized_patients(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_facility_authorized_patients(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.trip_contact_attachment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.saved_patients; c public.provider_contacts; BEGIN
IF TG_OP='UPDATE' THEN IF NEW.saved_patient_id IS DISTINCT FROM OLD.saved_patient_id OR NEW.coordination_contact_id IS DISTINCT FROM OLD.coordination_contact_id OR NEW.payer_id IS DISTINCT FROM OLD.payer_id THEN RAISE EXCEPTION 'Trip billing/contact references are immutable'; END IF; RETURN NEW; END IF;
IF NEW.payer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.payers x WHERE x.id=NEW.payer_id AND x.active AND x.workspace_id=NEW.workspace_id AND public.authorized_trip_record(NEW.actor_user_id,NEW.workspace_id,'payers',x.id)) THEN RAISE EXCEPTION 'Payer not available'; END IF;
IF NEW.coordination_contact_id IS NOT NULL THEN SELECT * INTO c FROM public.provider_contacts WHERE id=NEW.coordination_contact_id AND active AND coordination_allowed AND workspace_id=NEW.workspace_id; IF c.id IS NULL OR NOT public.authorized_trip_record(NEW.actor_user_id,NEW.workspace_id,'contacts',c.id) THEN RAISE EXCEPTION 'Contact not available'; END IF; END IF;
IF NEW.saved_patient_id IS NOT NULL THEN SELECT * INTO p FROM public.saved_patients WHERE id=NEW.saved_patient_id AND active AND kind='patient'; IF p.id IS NULL OR NOT (p.owner_id=NEW.actor_user_id OR p.workspace_id=NEW.workspace_id AND EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=p.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL) OR p.patient_workspace_id=NEW.patient_workspace_id AND EXISTS(SELECT 1 FROM public.workspaces w JOIN public.account_business_connections b ON b.active AND b.workspace_a=least(w.id,NEW.workspace_id) AND b.workspace_b=greatest(w.id,NEW.workspace_id) WHERE w.id=p.workspace_id AND w.status='active' AND NOT w.is_test_account AND w.account_type IN ('facility','hospital')) AND EXISTS(SELECT 1 FROM public.account_business_connections b WHERE b.active AND b.workspace_a=least(p.workspace_id,NEW.patient_workspace_id) AND b.workspace_b=greatest(p.workspace_id,NEW.patient_workspace_id)) AND EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL)) THEN RAISE EXCEPTION 'Patient not available'; END IF; END IF;
RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.audit_contact_payer_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='provider_contacts' THEN UPDATE public.provider_contacts SET workspace_mfn_id=(SELECT mfn_id FROM public.workspaces WHERE id=NEW.workspace_id) WHERE id=NEW.id AND workspace_mfn_id IS NULL; END IF;
IF pg_trigger_depth()>1 THEN RETURN NEW; END IF;
INSERT INTO public.account_security_audit(user_id,sender_mfn_id,workspace_id,workspace_mfn_id,event_type,result) VALUES(auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),NEW.workspace_id,(SELECT mfn_id FROM public.workspaces WHERE id=NEW.workspace_id),'contact_payer_'||lower(TG_OP),jsonb_build_object('record_kind',TG_TABLE_NAME,'record_id',NEW.id)::text);
RETURN NEW; END $$;
CREATE TRIGGER audit_contact_change AFTER INSERT OR UPDATE ON public.provider_contacts FOR EACH ROW EXECUTE FUNCTION public.audit_contact_payer_change();
CREATE TRIGGER audit_payer_change AFTER INSERT OR UPDATE ON public.payers FOR EACH ROW EXECUTE FUNCTION public.audit_contact_payer_change();
COMMENT ON COLUMN public.saved_patients.patient_workspace_id IS 'Explicit confirmed Facility-to-patient mapping; no matching or backfill. Provider selection also requires both active bilateral connections.';